);
CREATE TABLE IF NOT EXISTS config_history (
	id          INTEGER PRIMARY KEY AUTOINCREMENT,
	flag_key    TEXT NOT NULL,
	environment TEXT NOT NULL,
	version     TEXT NOT NULL UNIQUE,
	enabled     INTEGER NOT NULL,
