package api

import (
	"encoding/json"
	"net/http"
	"reflect"
	"testing"
)

func getChangesBody(t *testing.T, h *apiHarness, path string) (int, map[string]any) {
	t.Helper()
	rec := h.do(t, http.MethodGet, path, "")
	var body map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode: %v: %s", err, rec.Body.String())
	}
	return rec.Code, body
}

func asItems(t *testing.T, body map[string]any) []any {
	t.Helper()
	items, ok := body["items"].([]any)
	if !ok {
		t.Fatalf("items not an array: %#v", body["items"])
	}
	return items
}

func asStringSlice(t *testing.T, v any) []string {
	t.Helper()
	raw, ok := v.([]any)
	if !ok {
		t.Fatalf("changed_fields not an array: %#v", v)
	}
	out := make([]string, 0, len(raw))
	for _, item := range raw {
		s, ok := item.(string)
		if !ok {
			t.Fatalf("changed_fields entry not a string: %#v", item)
		}
		out = append(out, s)
	}
	return out
}

func TestChangesAcrossFlagsUsesCreateUpdateDeleteActions(t *testing.T) {
	h := seededHarness(t)
	_, body := getChangesBody(t, h, "/api/v1/environments/prod/changes")
	if body["environment"] != "prod" {
		t.Fatalf("environment = %v, want prod", body["environment"])
	}
	items := asItems(t, h, body)
	if len(items) != 4 {
		t.Fatalf("items len = %d, want 4", len(items))
	}

	first := asMap(t, items[0])
	if first["flag_key"] != "checkout" || first["action"] != "created" {
		t.Fatalf("first item = %#v", first)
	}
	if first["before"] != nil {
		t.Errorf("created before = %v, want null", first["before"])
	}
	after := asMap(t, first["after"])
	if after["enabled"] != true || number(after["percentage"]) != 10 {
		t.Errorf("created after = %#v", after)
	}
	if got := asStringSlice(t, first["changed_fields"]); !reflect.DeepEqual(got, []string{"enabled", "percentage"}) {
		t.Errorf("created changed_fields = %v", got)
	}
	if first["changed_at"] != "2026-01-01T02:00:00Z" {
		t.Errorf("changed_at = %v", first["changed_at"])
	}

	second := asMap(t, items[1])
	if second["flag_key"] != "checkout" || second["action"] != "updated" {
		t.Fatalf("second item = %#v", second)
	}
	before := asMap(t, second["before"])
	if number(before["percentage"]) != 10 {
		t.Errorf("updated before percentage = %v, want 10", before["percentage"])
	}
	after = asMap(t, second["after"])
	if number(after["percentage"]) != 50 {
		t.Errorf("updated after percentage = %v, want 50", after["percentage"])
	}
	if got := asStringSlice(t, second["changed_fields"]); !reflect.DeepEqual(got, []string{"percentage"}) {
		t.Errorf("updated changed_fields = %v, want [percentage]", got)
	}

	third := asMap(t, items[2])
	if third["flag_key"] != "coupon" || third["action"] != "created" {
		t.Fatalf("third item = %#v", third)
	}

	fourth := asMap(t, items[3])
	if fourth["flag_key"] != "checkout" || fourth["action"] != "deleted" {
		t.Fatalf("fourth item = %#v", fourth)
	}
	if fourth["after"] != nil {
		t.Errorf("deleted after = %v, want null", fourth["after"])
	}
	before = asMap(t, fourth["before"])
	if before["enabled"] != true || number(before["percentage"]) != 50 {
		t.Errorf("deleted before = %#v", before)
	}
	if got := asStringSlice(t, fourth["changed_fields"]); !reflect.DeepEqual(got, []string{"enabled", "percentage"}) {
		t.Errorf("deleted changed_fields = %v", got)
	}
}

func TestChangesOrdersByChangedAtThenWriteOrder(t *testing.T) {
	h := newHarness(t)
	h.createEnv(t, "prod")
	h.createFlag(t, "alpha")
	h.createFlag(t, "beta")
	h.setTime("2026-03-01T00:00:00Z")
	h.putConfig(t, "prod", "alpha", `{"enabled":true,"percentage":1}`)
	h.putConfig(t, "prod", "beta", `{"enabled":true,"percentage":2}`)
	h.setTime("2026-03-01T01:00:00Z")
	h.putConfig(t, "prod", "beta", `{"enabled":true,"percentage":3}`)

	_, body := getChangesBody(t, h, "/api/v1/environments/prod/changes")
	items := asItems(t, h, body)
	got := make([][2]string, 0, len(items))
	for _, item := range items {
		row := asMap(t, item)
		got = append(got, [2]string{row["changed_at"].(string), row["flag_key"].(string)})
	}
	want := [][2]string{
		{"2026-03-01T00:00:00Z", "alpha"},
		{"2026-03-01T00:00:00Z", "beta"},
		{"2026-03-01T01:00:00Z", "beta"},
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("order = %#v, want %#v", got, want)
	}
}

func TestChangesFilteredByFlagKey(t *testing.T) {
	h := seededHarness(t)
	_, body := getChangesBody(t, h, "/api/v1/environments/prod/changes?flagKey=checkout")
	items := asItems(t, h, body)
	if len(items) != 3 {
		t.Fatalf("items len = %d, want 3", len(items))
	}
	for _, item := range items {
		if asMap(t, item)["flag_key"] != "checkout" {
			t.Fatalf("unexpected flag: %#v", item)
		}
	}
}

func TestChangesFromToWindowIsHalfOpen(t *testing.T) {
	h := seededHarness(t)
	// from is inclusive: matches 03:00 (updated) and 06:00 (coupon created).
	_, body := getChangesBody(t, h, "/api/v1/environments/prod/changes?from=2026-01-01T03:00:00Z&to=2026-01-01T08:00:00Z")
	items := asItems(t, h, body)
	if len(items) != 2 {
		t.Fatalf("items len = %d, want 2", len(items))
	}
	if asMap(t, items[0])["action"] != "updated" {
		t.Errorf("first = %#v, want updated", items[0])
	}
	if asMap(t, items[1])["flag_key"] != "coupon" {
		t.Errorf("second = %#v, want coupon created", items[1])
	}
}

func TestChangesClassifiesRecordsOutsideWindowByFullChain(t *testing.T) {
	h := seededHarness(t)
	// The 08:00 tombstone must still read as "deleted": its predecessor
	// (03:00 update) is outside the window but drives action classification.
	_, body := getChangesBody(t, h, "/api/v1/environments/prod/changes?from=2026-01-01T07:00:00Z")
	items := asItems(t, h, body)
	if len(items) != 1 {
		t.Fatalf("items len = %d, want 1", len(items))
	}
	item := asMap(t, items[0])
	if item["action"] != "deleted" {
		t.Fatalf("action = %v, want deleted", item["action"])
	}
	before := asMap(t, item["before"])
	if number(before["percentage"]) != 50 {
		t.Errorf("before percentage = %v, want 50", before["percentage"])
	}
}

func TestChangesRecreateAfterTombstoneIsCreated(t *testing.T) {
	h := seededHarness(t)
	h.setTime("2026-01-02T01:00:00Z")
	h.putConfig(t, "prod", "checkout", `{"enabled":true,"percentage":77}`)
	_, body := getChangesBody(t, h, "/api/v1/environments/prod/changes?flagKey=checkout&from=2026-01-02T00:00:00Z")
	items := asItems(t, h, body)
	if len(items) != 1 {
		t.Fatalf("items len = %d, want 1", len(items))
	}
	item := asMap(t, items[0])
	if item["action"] != "created" {
		t.Fatalf("action = %v, want created after tombstone", item["action"])
	}
	if item["before"] != nil {
		t.Errorf("before = %v, want null", item["before"])
	}
	if number(asMap(t, item["after"])["percentage"]) != 77 {
		t.Errorf("after percentage = %v, want 77", asMap(t, item["after"])["percentage"])
	}
}

func TestChangesWindowFieldsAppearInFixedOrder(t *testing.T) {
	h := newHarness(t)
